p.write_text('''def transform(grid):
    # Fill each cell using the color of the nearest marked diagonal (constant row+column).
    h, w = len(grid), len(grid[0])
    bands = {}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v: bands.setdefault(r+c, v)
    keys=sorted(bands)
    return [[bands[min(keys, key=lambda k:(abs(r+c-k), k))] for c in range(w)] for r in range(h)]
''')
